import unittest

from hourglass.rounding import label_spans, snap_span
from hourglass.models import Span

class SnapTests(unittest.TestCase):
    def test_rounds_to_nearest_step(self):
        snapped = snap_span(Span(541, 1028), 15)
        self.assertEqual(snapped, Span(540, 1035))

    def test_halves_round_up(self):
        snapped = snap_span(Span(555, 600), 30)
        self.assertEqual(snapped, Span(570, 600))

    def test_span_collapsing_to_nothing_is_rejected(self):
        with self.assertRaises(ValueError):
            snap_span(Span(541, 545), 15)

class LabelTests(unittest.TestCase):
    def test_label_shows_clock_range_and_length(self):
        labels = label_spans([Span(541, 1028)], 15)
        self.assertEqual(labels, ["09:00-17:15 (8h 15m)"])

    def test_label_under_an_hour(self):
        labels = label_spans([Span(555, 600)], 30)
        self.assertEqual(labels, ["09:30-10:00 (0h 30m)"])

    def test_steps_that_divide_an_hour_are_accepted(self):
        spans = [Span(540, 600)]
        for step in (1, 5, 20, 60):
            with self.subTest(step=step):
                labels = label_spans(spans, step)
                self.assertEqual(len(labels), 1)

    def test_bad_steps_are_rejected(self):
        spans = [Span(540, 600)]
        for step in (0, -15, 7, 90):
            with self.subTest(step=step):
                with self.assertRaises(ValueError):
                    label_spans(spans, step)
